# Generated by sila2.code_generator; sila2.__version__: 0.14.0, then implemented by hand.
"""Simulated Peltier block B: a second, separately written implementation of the same
feature, so that a client written against the feature can be tried on two servers.

It is not independent of server A in SDK (both use sila_python), only in code and device
model: B ramps at a fixed 4 degC/s instead of approaching exponentially, publishes on change
only, and keeps its faults as a counter. Faults come from SIM_FAULT_FILE, in the same format
as server A.
"""

from __future__ import annotations

import json
import os
import time
from typing import TYPE_CHECKING

from sila2.server import MetadataDict

from ..generated.temperaturecontroller import (
    HeaterFault,
    ResetHeater_Responses,
    SetTargetTemperature_Responses,
    ShutDown_Responses,
    TemperatureControllerBase,
)

if TYPE_CHECKING:
    from ..server import Server

RAMP_C_PER_S = 4.0
IDLE_C = 25.0


class TemperatureControllerImpl(TemperatureControllerBase):
    def __init__(self, parent_server: Server) -> None:
        super().__init__(parent_server=parent_server)
        self._setpoint = IDLE_C
        self._reading = IDLE_C
        self._faults = 0
        self._last = time.monotonic()
        self._published = None
        self._publish()
        self.run_periodically(self._tick, delay_seconds=0.25)

    def _publish(self) -> None:
        value = round(self._reading, 2)
        if value != self._published:
            self._published = value
            self.update_CurrentTemperature(value)

    def _tick(self) -> None:
        now = time.monotonic()
        step = RAMP_C_PER_S * (now - self._last)
        self._last = now
        diff = self._setpoint - self._reading
        self._reading = self._setpoint if abs(diff) <= step else self._reading + step * (1 if diff > 0 else -1)
        self._publish()

    def _take_fault(self) -> dict:
        path = os.environ.get("SIM_FAULT_FILE")
        if path and os.path.exists(path):
            with open(path, encoding="utf-8") as f:
                fault = json.load(f)
            os.remove(path)
            return fault
        return {}

    def get_TargetTemperature(self, *, metadata: MetadataDict) -> float:
        return self._setpoint

    def get_HeaterFaulted(self, *, metadata: MetadataDict) -> bool:
        return self._faults > 0

    def SetTargetTemperature(self, TargetTemperature: float, *, metadata: MetadataDict) -> SetTargetTemperature_Responses:
        fault = self._take_fault()
        self._faults += 1 if fault.get("heater_fault") else 0
        if self._faults:
            raise HeaterFault(f"Peltier block B reports {self._faults} unacknowledged fault(s)")
        self._setpoint = float(TargetTemperature)
        if fault.get("next_set") == "apply_then_delay":
            time.sleep(float(fault.get("delay_s", 8)))
        return SetTargetTemperature_Responses()

    def ResetHeater(self, *, metadata: MetadataDict) -> ResetHeater_Responses:
        self._faults = 0
        return ResetHeater_Responses()

    def ShutDown(self, *, metadata: MetadataDict) -> ShutDown_Responses:
        self._setpoint = IDLE_C
        return ShutDown_Responses()
